#!/usr/bin/env python3
"""Translate the pinned, bundled Flash UCS2 mapping data into C++98 arrays."""
from pathlib import Path
import re
root = Path(__file__).resolve().parent.parent
base = root / "external/flash_case"
source = (base / "tables.rs").read_text()
parts = ["/* Flash UCS2 case mappings from pinned Ruffle wstr/src/tables.rs.\n"
         " * Copyright Ruffle contributors; MIT license in LICENSE.md.\n"
         " * Generated by scripts/generate_flash_case.py; do not edit. */\n"
         "#ifndef FVM_FLASH_CASE_TABLE_HPP\n#define FVM_FLASH_CASE_TABLE_HPP\n"]
for name, body in re.findall(r"pub static (\w+)_TABLE:.*?= &\[(.*?)\];", source, re.S):
    pairs = [(int(a), int(b)) for a, b in re.findall(r"\((\d+), (\d+)\)", body)]
    assert pairs and all(0 <= a <= 65535 and 0 <= b <= 65535 for a, b in pairs)
    assert all(pairs[i-1][0] < pairs[i][0] for i in range(1, len(pairs)))
    parts.append("/* Sorted source/target UCS2 units, with one output per input. */\n")
    parts.append("static const unsigned short fvm_flash_%s[][2] = {\n" % name.lower())
    parts.extend("    {0x%04x, 0x%04x},\n" % pair for pair in pairs)
    parts.append("};\n")
assert len(re.findall(r"static const unsigned short", "".join(parts))) == 2
parts.append("#endif\n")
(base / "case_table.hpp").write_text("".join(parts))
